/**
 * Mask Shape Library
 * SVG shape presets for vector mask system
 */

export type MaskShapeCategory = 'core' | 'hud' | 'symbols' | 'abstract' | 'organic' | 'pattern' | 'custom';

export interface ShapePreset {
  id: string;
  name: string;
  category: MaskShapeCategory;
  svgPath: string;
  viewBox: { x: number; y: number; w: number; h: number };
  complexity: 'simple' | 'detailed';
  renderMode: 'fill' | 'wireframe';  // How to render the shape
  defaultStrokeWidth?: number;       // Default stroke width for wireframe shapes (1-20)
  description?: string;              // Optional description for custom shapes
  tags?: string[];                   // Optional tags for filtering/search
}

export const MASK_SHAPE_CATEGORY_ORDER: MaskShapeCategory[] = [
  'core',
  'hud',
  'symbols',
  'abstract',
  'organic',
  'pattern',
  'custom',
];

// ── Raster mask lazy loader — Sprint B ──────────────────────────────────────
// The 5 base64-PNG masks live in maskShapesRaster.ts, a separate Vite code-split
// chunk (~155KB). They are NOT included in the main bundle — loaded on first call.
// MaskControls calls loadRasterMasks() on mount; the result is cached forever.
let _rasterCache: ShapePreset[] | null = null;

export function isUsableShapePreset(value: unknown): value is ShapePreset {
  if (!value || typeof value !== 'object') return false;
  const shape = value as Partial<ShapePreset>;
  return typeof shape.id === 'string'
    && shape.id.length > 0
    && typeof shape.name === 'string'
    && typeof shape.category === 'string'
    && typeof shape.svgPath === 'string'
    && !!shape.viewBox
    && Number.isFinite(shape.viewBox.w)
    && Number.isFinite(shape.viewBox.h);
}

export async function loadRasterMasks(): Promise<ShapePreset[]> {
  if (_rasterCache) return _rasterCache;
  const { RASTER_MASK_SHAPES } = await import('./maskShapesRaster');
  _rasterCache = Array.isArray(RASTER_MASK_SHAPES)
    ? RASTER_MASK_SHAPES.filter(isUsableShapePreset)
    : [];
  return _rasterCache;
}


export const MASK_SHAPE_CATEGORY_LABELS: Record<MaskShapeCategory, string> = {
  core: 'Core Geometry',
  hud: 'HUD / Tech',
  symbols: 'Symbols',
  abstract: 'Abstract Brand',
  organic: 'Organic / Fluid',
  pattern: 'Pattern Cells',
  custom: 'Custom / Imported',
};

export const MASK_SHAPE_CATEGORY_DESCRIPTIONS: Record<MaskShapeCategory, string> = {
  core: 'Clean foundational masks: circles, polygons, outlines, stars, and simple vector primitives.',
  hud: 'Tech-forward reticles, orbitals, brackets, nodes, and signal glyphs for futuristic masking.',
  symbols: 'Recognizable symbolic marks with strong identity and poster-design value.',
  abstract: 'Modern branding glyphs using offset, fractured, negative-space, and modular forms.',
  organic: 'Soft blobs, contours, waves, and fluid silhouettes for expressive mask motion.',
  pattern: 'Tile-friendly cells designed for the Shape Pattern texture system.',
  custom: 'User-loaded or imported vector shapes.',
};

export function getShapeCategoryLabel(category: MaskShapeCategory): string {
  return MASK_SHAPE_CATEGORY_LABELS[category];
}

