// COMBINED EXPORT - All geometric shapes (fill + wireframe) then all symbols, then custom
export const MASK_SHAPE_PRESETS: ShapePreset[] = [
  ...GEOMETRIC_SHAPES_FILL,
  ...GEOMETRIC_SHAPES_WIREFRAME,
  ...NEW_GEOMETRIC_SHAPES,
  ...SYMBOL_SHAPES,
  ...PREMIUM_GLYPH_PACK_V1,
  ...CUSTOM_SHAPES,
];

// Helper to get shapes by category.
// Pass _includeRaster=true (MaskControls passes rasterShapesLoaded) to include
// the lazily-loaded raster shapes once they are cached.
export function getShapesByCategory(category: MaskShapeCategory, _includeRaster = false): ShapePreset[] {
  const staticShapes = MASK_SHAPE_PRESETS.filter(
    (shape): shape is ShapePreset => isUsableShapePreset(shape) && shape.category === category,
  );
  if (_includeRaster && _rasterCache) {
    const rasterShapes = _rasterCache.filter(
      (shape): shape is ShapePreset => isUsableShapePreset(shape) && shape.category === category,
    );
    return [...staticShapes, ...rasterShapes];
  }
  return staticShapes;
}

// Helper to get shape by ID — checks static shapes first, then cached raster shapes.
// Persisted documents can temporarily reference removed shapes, and generated shape
// packs can contain sparse/undefined entries. This lookup must never throw.
export function getShapeById(id: string | null | undefined): ShapePreset | undefined {
  if (typeof id !== 'string' || id.length === 0) return undefined;

  const staticShape = MASK_SHAPE_PRESETS.find(
    (shape): shape is ShapePreset => isUsableShapePreset(shape) && shape.id === id,
  );
  if (staticShape) return staticShape;

  return _rasterCache?.find(
    (shape): shape is ShapePreset => isUsableShapePreset(shape) && shape.id === id,
  );
}

// Helper to add custom shapes programmatically
export function addCustomShape(shape: ShapePreset): void {
  if (shape.category !== 'custom') {
    console.warn('Only custom shapes can be added dynamically');
    return;
  }

  // Check for duplicate IDs
  const existing = getShapeById(shape.id);
  if (existing) {
    console.warn(`Shape with id "${shape.id}" already exists`);
    return;
  }

  CUSTOM_SHAPES.push(shape);
}

// Helper to get all custom shapes
export function getCustomShapes(): ShapePreset[] {
  return CUSTOM_SHAPES;
}

// Helper to count shapes by category
export function getShapeCount(): Record<MaskShapeCategory, number> & { total: number } {
  return {
    core: getShapesByCategory('core').length,
    hud: getShapesByCategory('hud').length,
    symbols: getShapesByCategory('symbols').length,
    abstract: getShapesByCategory('abstract').length,
    organic: getShapesByCategory('organic').length,
    pattern: getShapesByCategory('pattern').length,
    custom: getShapesByCategory('custom').length,
    total: MASK_SHAPE_PRESETS.length,
  };
}